function is_food_for( $product_id, $species ){
		$cat = self::species_cat( $species );
		if ( ! $cat ) return false;
		$ids = array( $cat );
		$kids = get_term_children( $cat, 'product_cat' );
		if ( is_array($kids) ) $ids = array_merge( $ids, array_map('intval',$kids) );
		return has_term( $ids, 'product_cat', (int) $product_id );
	}

