rez.fn_species_cat:
function species_cat( $species ){
		$s = (string) $species;
		return isset( self::SPECIES_CAT[$s] ) ? self::SPECIES_CAT[$s] : 0;
	}

	/** S224: pasiulymu kategorijos — TIK skanestai/zaislai/prieziura/papildai/guoliai/antkakliai.
	 * Aksesuarai gyvena po TOP "SUNIMS/KATEMS" tevais, ne po maisto saknim (71/78) — todel ID zemelapis. */
	const SUGGEST_CAT = array(
		'dog'    => array( 95, 115, 101, 82, 76, 233, 116 ),
		'cat'    => array( 96, 114, 102, 130, 569, 117 ),
		'rodent' => array( 97 ),
		'bird'   => array( 98 ),
	);
	private static function suggest_terms( $species ){
		return isset( self::SUGGEST_CAT[ (string) $species ] ) ? self::SUGGEST_CAT[ (string) $species ] : array();
	}

	/** Alergenu raktazodziai pavadinimo filtrui (tik valgomoms kategorijoms). */
	private static function allergen_words( $sens ){
		$map = array(
			'chicken' => array('vištien','vistien','chicken'),
			'beef'    => array('jautien','beef'),
			'grains'  => array('grūd','grud','kvieč','kviec','miež','miez','grain'),
			'dairy'   => array('pien','sūr','sur'),
			'fish'    => array('žuv','zuv','lašiš','lasis','menk','tun','silk'),
		);
		$out = array();
		foreach ( explode( ',', (string) $sens ) as $c ) {
			$c = trim( $c );
			if ( isset( $map[$c] ) ) { foreach ( $map[$c] as $w ) { $out[] = json_decode('"'.$w.'"') ?: $w; } }
		}
		return $out;
	}

